def transform(grid):
    g=[row[:] for row in grid]
    for cells in regions(grid):
        nz=[(r,c) for r,c in cells if grid[r][c]!=0]
        if not nz: continue
        pt=min(r for r,c in nz); pl=min(c for r,c in nz)
        ph=max(r for r,c in nz)-pt+1; pw=max(c for r,c in nz)-pl+1
        pat=[[grid[pt+a][pl+b] for b in range(pw)] for a in range(ph)]
        for r,c in cells:
            g[r][c]=pat[(r-pt)%ph][(c-pl)%pw]
    return g
